/* --- 5 personnages (renommés depuis Erwan/Baptiste/JB/Steph/Fab) --- */
function mkChar(o) {
  const modifiers = (window.DEFAULT_MODIFIERS && window.DEFAULT_MODIFIERS[o.id]) || {};
  return { ...o, attrs:{ force:o.F, hab:o.H, mental:o.M, magie:o.C }, modifiers };
}

